def gen(rng):
    def fmt(g):
        return f"{len(g)} {len(g[0])}\n" + "\n".join(''.join(map(str, row)) for row in g)
    def rand_grid(r, c, p):
        return [[1 if rng.random() < p else 0 for _ in range(c)] for _ in range(r)]
    def rand_shape(k):
        cells = {(0, 0)}
        while len(cells) < k:
            x, y = rng.choice(sorted(cells))
            dx, dy = rng.choice(((1, 0), (-1, 0), (0, 1), (0, -1)))
            cells.add((x + dx, y + dy))
        mx = min(p for p, q in cells)
        my = min(q for p, q in cells)
        return [(p - mx, q - my) for p, q in cells]
    def placed(r, c, templates, tries):
        g = [[0] * c for _ in range(r)]
        for _ in range(tries):
            t = rng.choice(templates)
            h = max(p for p, q in t) + 1
            w = max(q for p, q in t) + 1
            if h > r or w > c:
                continue
            oi = rng.randint(0, r - h)
            oj = rng.randint(0, c - w)
            ok = True
            for p, q in t:
                i, j = oi + p, oj + q
                if g[i][j]:
                    ok = False
                    break
                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = i + di, j + dj
                    if 0 <= a < r and 0 <= b < c and g[a][b]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                for p, q in t:
                    g[oi + p][oj + q] = 1
        return g
    tests = [fmt([[1]]), fmt([[0]]), fmt([[0, 0], [0, 0]]), fmt([[1, 1], [1, 1]]),
